function parseChartConfig(canvas){const rawConfig=canvas.dataset.chartConfig;if(!rawConfig){return null;}try{return JSON.parse(rawConfig);}catch{canvas.dataset.chartError="invalid-config";return null;}}function renderCharts(){if(!window.Chart){return;}document.querySelectorAll("canvas[data-chart-config]").forEach((canvas)=>{if(canvas.dataset.chartInitialized==="true"){return;}const config=parseChartConfig(canvas);if(!config){return;}new window.Chart(canvas,config);canvas.dataset.chartInitialized="true";});}renderCharts();
